/bin/bash -lc "rg -n 'LLM|llm|summariz|LeMUR|speech_models' /home/agent/.local/lib/python3.12/site-packages/assemblyai-1.10.0.dist-info/METADATA | tail -70; ls /home/agent/.local/lib/python3.12/site-packages/assemblyai; sed -n '1,250p' /home/agent/.local/lib/python3.12/site-packages/assemblyai/llm_gateway.py; python - <<'PY'
import httpx, os
for url in ['https://api.assemblyai.com/v2/transcript?limit=1','https://www.assemblyai.com/docs/llms.txt','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/MIGRATION.md']:
 try:
  headers={'authorization':os.environ['ASSEMBLYAI_API_KEY']} if 'api.assemblyai.com' in url else {}
  r=httpx.get(url,headers=headers,timeout=20,follow_redirects=True)
  print(url, r.status_code, r.text[:10000])
 except Exception as e: print(url,type(e).__name__,str(e))
PY"

